text:
// Pawn Champ - The Toboggan. Minor quest m71, batch N (docs/quests/MINOR.md#m71-the-toboggan).
// The town's first-snow run down Teague's Hill needs the old eight-seat toboggan, and the Brodeurs
// have just pawned it. Every kid who ever rode it carved their name in it, Odile's included.
// Hand it back for the run, steer the first run yourself, or sell it to a ski lodge.
// December to February, in a stay. The run is on the hill above Hob's Pond (`icepondSled`).
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call. Code half: js/quests/toboggan.js.
defineStory({
  "id": "toboggan",
  "kind": "minor",
  "title": "The Toboggan",
  "location": "icepond",
  "months": [3, 4, 5],
  "rumour": "The first-snow run down Teague's Hill needs the old Brodeur toboggan, and the Brodeurs have pawned it.",
  "endings": { "run": "The First Run", "front": "Front Seat", "lodge": "On the Lodge Wall" },
  "outcome": "flag.tobogganEnd",
  "about": [
    "A winter story. Gerry Brodeur pawns his grandfather's eight-seat 1948 toboggan, which every kid on the Hob Pond road has ridden down Teague's Hill, because his furnace went (§{tobogganGerry}). Ward Dunlevy offers $280 for it to hang over a ski-lodge fireplace in North Conway (§{tobogganOffer}). Sell it (On the Lodge Wall), or say it's spoken for and Skip tells you the first good snow is this week.",
    "On Teague's Hill (§{tobogganRun}) Gerry hasn't got the money yet. Hand it back free for the first run of the year (The First Run), or steer the first run yourself with seven screaming children behind you and end up in a heap by the hockey net (Front Seat). Either way your name gets carved into it."
  ],
  "cast": {
    "gerry": {
      "name": "Gerry Brodeur",
      "look": { "skin": "#e8c0a0", "hair": "#6a4a2a", "hs": 0, "coat": "#c83a2a", "trim": "#2a2a2a", "style": "puffer", "hat": "beanie", "hatc": "#2a5a3a", "pants": "#2a3a5a", "beard": "#6a4a2a", "stout": true }
    },
    "dunlevy": {
      "name": "Ward Dunlevy",
      "look": { "skin": "#f0d0b8", "hair": "#a8a8a8", "hs": 2, "coat": "#2a3a2a", "trim": "#c8a050", "style": "jacket", "pants": "#5a4a3a", "glasses": "#2a2a2e" }
    }
  },
  "icons": {
    "toboggan": [
      "............",
      ".kk.........",
      "kWWk........",
      "kWnk........",
      "kWWkkkkkkkkk",
      ".kWWWWWWWWWk",
      ".kWnWnWnWnWk",
      ".kWWWWWWWWWk",
      "..kkkkkkkkk.",
      "............",
      "............",
      "............"
    ]
  },
  "uniques": {
    "toboggan": {
      "name": "An eight-seat toboggan, 1948",
      "icon": "toboggan",
      "cat": "curio",
      "guide": 160,
      "condLabel": "Names carved all over it",
      "questKey": true,
      "tells": [
        "Ash slats steamed and curled at the front, eight feet long. BRODEUR burned into the curl.",
        "Names carved in every slat, seventy years of them. Near the back, small and neat: ODILE 1961."
      ]
    }
  },
  "spots": {
    "icepondSled": [
      {
        "id": "lanterns",
        "rect": { "x": 20, "y": 90, "w": 200, "h": 110 },
        "lines": [
          "Lanterns all the way down the run, so the last runs can go on after dark. Somebody's mother does this every year."
        ]
      },
      {
        "id": "crowd",
        "rect": { "x": 0, "y": 84, "w": 130, "h": 30 },
        "lines": ["Forty children at the top of the hill, negotiating seats on a toboggan that has eight."],
        "where": "Teague's Hill",
        "find": { "on": 1, "coin": 1, "line": "A dollar in the snow at the top of the run, with a mitten. The mitten goes on the fence post. The dollar goes in your pocket." }
      }
    ]
  },
  "scenes": {
    "tobogganGerry": {
      "title": "Gerry Brodeur pawns the family toboggan",
      "customer": "gerry",
      "steps": [
        {
          "say": "gerry",
          "text": [
            "Gerry Brodeur. Dad's toboggan. Eight seats. My grandfather built it in '48 and every kid on the Hob Pond road has ridden it down Teague's Hill.",
            "The furnace went. I need ninety dollars by Friday. I'll be back for it, honest."
          ]
        },
        { "offer": { "unique": "toboggan" }, "persona": "desperate", "asking": 90, "min": 60 },
        {
          "if": "offer != 'deal'",
          "then": [
            { "say": "gerry", "text": "OK. OK. I'll try the guy on Route 1." },
            { "leave": "gerry" },
            { "end": true }
          ]
        },
        { "set": { "tobogganIn": true } },
        { "say": "gerry", "text": "Don't let anybody sit on it. It knows when it's not us." },
        { "leave": "gerry" }
      ]
    },
    "tobogganOffer": {
      "title": "A man furnishing a ski lodge wants the toboggan",
      "customer": "dunlevy",
      "steps": [
        { "find": "t", "in": "stock", "match": { "uniqueId": "toboggan" } },
        {
          "if": "!t",
          "then": [
            { "say": "dunlevy", "text": "I was told you had an antique toboggan. No? A pity. I'm furnishing a ski lodge in North Conway." },
            { "leave": "dunlevy" },
            { "end": true }
          ]
        },
        {
          "say": "dunlevy",
          "text": [
            "Ward Dunlevy. I'm furnishing a ski lodge in North Conway, and that toboggan, over the fireplace, with all those names on it, is exactly the thing.",
            "Two hundred and eighty. The guests will make up stories about the names. That's what guests are for."
          ]
        },
        {
          "choose": [
            {
              "label": "Sell it to the lodge",
              "hint": "(+$280; the story ends here)",
              "then": [
                { "take": "t" },
                { "coin": 280, "why": "Sold the Brodeur toboggan to a ski lodge" },
                { "rep": -2 },
                { "set": { "tobogganEnd": "lodge" } },
                { "say": "dunlevy", "text": "Splendid. It'll be very happy. It'll never go outside again, but it'll be very happy." }
              ]
            },
            {
              "label": "\"It's spoken for.\"",
              "then": [
                { "say": "dunlevy", "text": "Of course. If it becomes unspoken, here's my card." },
                { "narrate": "An hour later Skip Fairweather leans in from the bus stop: the first good snow is this week, and the whole route is asking if the Brodeur toboggan will be on the hill." },
                { "set": { "tobogganRun": true } },
                { "plan": "toboggan-run" }
              ]
            }
          ]
        },
        { "leave": "dunlevy" }
      ]
    },
    "tobogganRun": {
      "title": "The first run down Teague's Hill",
      "steps": [
        { "find": "t", "in": "stock", "match": { "uniqueId": "toboggan" } },
        {
          "if": "t",
          "then": [{ "hook": "pond", "with": { "toboggan": true } }],
          "else": [{ "hook": "pond", "with": { "toboggan": false } }]
        },
        {
          "stage": "icepondSled",
          "fadeOut": false,
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [110, 168] },
            { "id": "gerry", "cast": "gerry", "at": [176, 166], "facingLeft": true },
            { "id": "skip", "cast": "skip", "at": [230, 166], "facingLeft": true, "if": "hook.skipHere" }
          ]
        },
        { "narrate": "Noon on Teague's Hill. Fresh snow, lanterns already lit down the run for later, and forty children at the top in a state of mind." },
        { "say": "skip", "text": "Half my route's here. The other half are on their way. I said I'd drive them. I'm on my lunch.", "if": "skip" },
        {
          "if": "!t",
          "then": [
            { "say": "gerry", "text": "You sold it? To who? ...Right. We'll use trays." },
            { "set": { "tobogganEnd": "lodge" } },
            { "end": true }
          ]
        },
        { "say": "gerry", "text": "You brought it. You actually brought it up the hill. I haven't got the ninety yet." },
        {
          "choose": [
            {
              "label": "Hand it to the Brodeurs, ticket and all",
              "hint": "(free)",
              "then": [
                { "take": "t" },
                { "rep": 4, "why": "Gave the Brodeur toboggan back for the first run" },
                { "set": { "tobogganEnd": "run" } },
                { "narrate": "Eight children pile on behind Gerry. The toboggan goes down Teague's Hill like a dropped piano, across the bottom, and out onto the ice of Hob's Pond in a long howling curve. Everyone wants to go again. Everyone goes again." },
                { "say": "gerry", "text": "Pay you back by spring. And you're carving your name in it. That's the rule." }
              ]
            },
            {
              "label": "Steer the first run yourself",
              "hint": "(then hand it back)",
              "then": [
                { "take": "t" },
                { "rep": 3, "why": "Steered the first run down Teague's Hill" },
                { "set": { "tobogganEnd": "front" } },
                {
                  "narrate": [
                    "You sit in the front, at the curl, with seven children behind you holding on to each other and screaming in advance. Gerry pushes off.",
                    "You don't steer it. Nobody steers it. It goes where it's been going since 1948, down the hill, across the bottom and out onto the pond, and you all come off in a heap by the hockey net."
                  ]
                },
                { "say": "gerry", "text": "Front seat on the first run. You're in the book now. Somebody get a knife, they're carving their name." }
              ]
            }
          ]
        }
      ]
    }
  },
  "beats": [
    { "drift": "toboggan", "from": "1-2", "to": "2-2", "cast": "gerry", "scene": "tobogganGerry" },
    { "drift": "toboggan", "from": "1-2", "to": "2-2", "offset": 3, "cast": "dunlevy", "scene": "tobogganOffer", "if": "flag.tobogganIn && !flag.tobogganEnd" }
  ],
  "errands": [
    {
      "id": "toboggan-run",
      "title": "The first run down Teague's Hill",
      "where": "Teague's Hill, above Hob's Pond",
      "scene": "tobogganRun",
      "test": [{ "add": { "unique": "toboggan" } }, { "set": { "tobogganRun": true } }]
    }
  ],
  "calendar": [
    { "id": "toboggan-run", "errand": "toboggan-run", "story": "toboggan", "where": "Teague's Hill", "title": "The first run", "known": "flag.tobogganRun" }
  ],
  "epilogue": [
    { "line": "The Brodeur toboggan went down Teague's Hill on the first snow, as it has every year since 1948. There's a new name carved near the back. Yours.", "if": "flag.tobogganEnd == 'run'" },
    { "line": "You rode the front seat of the Brodeur toboggan on the first run, and came off by the hockey net. Your name is carved under Odile's.", "if": "flag.tobogganEnd == 'front'" },
    { "line": "The Brodeur toboggan hangs over a fireplace in North Conway. The kids on the Hob Pond road use cafeteria trays now.", "if": "flag.tobogganEnd == 'lodge'" }
  ],
  "talk": {
    "by": "skip",
    "rumour": [
      "First good snow this week. The whole route wants to go down Teague's Hill on the Brodeur toboggan. Eight seats. Built in '48.",
      "Only Gerry Brodeur's furnace went, and the toboggan's gone to a pawnshop. Which one, I wonder."
    ],
    "react": { "run": "The Brodeur toboggan went down Teague's Hill on the first snow. Forty kids. Four broken mittens. Best day of the year on my bus.", "front": "I hear you rode the front seat on the first run and came off by the hockey net. The kids voted it the best crash of the winter.", "lodge": "The Brodeur toboggan's gone to a ski lodge. The kids are using lunch trays. They're very fast, as it happens, and very sad." }
  }
});
